const canvas=document.querySelector('#paint'),ctx=canvas.getContext('2d');
const mask=document.createElement('canvas'),m=mask.getContext('2d');
const ink=document.createElement('canvas'),k=ink.getContext('2d');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let w,h,dpr,base,size,left,textWidth,start=performance.now(),pointer={x:-1000,y:-1000},trail=[];
const seeds=Array.from({length:31},(_,i)=>({x:(i+.4)/31,length:22+((i*47)%125),speed:.3+(i%7)*.1,width:2+(i%4)*1.1,phase:i*1.73}));
function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);for(const c of [canvas,mask,ink]){c.width=w*dpr;c.height=h*dpr;}for(const c of [ctx,m,k])c.setTransform(dpr,0,0,dpr,0,0);size=w<600?w*.26:w*.255;base=h*.57; m.font=`900 ${size}px Impact, 'Arial Black', sans-serif`;textWidth=m.measureText('FRANCO').width;const scale=(w*.9)/textWidth;left=w*.05;m.save();m.translate(left,base);m.transform(scale,0,-.13,1,0,0);m.fillText('FRANCO',0,0);m.restore();textWidth=w*.9;}
function draw(now){const t=reduced?2:(now-start)/1000;ctx.clearRect(0,0,w,h);k.clearRect(0,0,w,h);k.fillStyle='#121311';k.fillRect(0,0,w,h);k.globalCompositeOperation='destination-in';k.drawImage(mask,0,0,w,h);k.globalCompositeOperation='source-over';
// Drips are attached only where the letter mask reaches the baseline.
for(const s of seeds){const x=left+s.x*textWidth;const pix=m.getImageData(Math.max(0,Math.floor(x*dpr)),Math.floor((base-5)*dpr),1,1).data;if(pix[3]<100)continue;const len=s.length*Math.min(1,t*.16)*(1+.15*Math.sin(t*s.speed+s.phase));k.beginPath();k.moveTo(x-s.width,base-9);k.bezierCurveTo(x-s.width,base+len*.7,x-1,base+len,x,base+len);k.bezierCurveTo(x+s.width*1.7,base+len,x+s.width,base+len*.3,x+s.width,base-9);k.fill();}
ctx.save();ctx.fillStyle='#d5ff34';ctx.fillRect(0,0,w,h);ctx.globalCompositeOperation='destination-in';ctx.drawImage(mask,0,0,w,h);ctx.restore();
k.globalCompositeOperation='destination-out';trail=trail.filter(p=>now-p.time<1400);for(const p of trail){const age=(now-p.time)/1400,r=(w<600?45:65)*(1-age);if(r<=0)continue;const gradient=k.createRadialGradient(p.x,p.y,0,p.x,p.y,r);gradient.addColorStop(0,'rgba(0,0,0,.95)');gradient.addColorStop(.7,'rgba(0,0,0,.85)');gradient.addColorStop(1,'rgba(0,0,0,0)');k.fillStyle=gradient;k.beginPath();k.arc(p.x,p.y,r,0,Math.PI*2);k.fill();}k.globalCompositeOperation='source-over';ctx.drawImage(ink,0,0,w,h);
if(pointer.x>0){ctx.strokeStyle='rgba(18,19,17,.3)';ctx.lineWidth=.8;ctx.beginPath();ctx.arc(pointer.x,pointer.y,12,0,Math.PI*2);ctx.stroke();}requestAnimationFrame(draw);}
canvas.addEventListener('pointermove',e=>{pointer={x:e.clientX,y:e.clientY};trail.push({...pointer,time:performance.now()});if(trail.length>70)trail.shift();});canvas.addEventListener('pointerleave',()=>pointer.x=-1000);canvas.addEventListener('pointerdown',e=>trail.push({x:e.clientX,y:e.clientY,time:performance.now()}));addEventListener('resize',resize);resize();requestAnimationFrame(draw);
document.querySelector('#enter').addEventListener('click',()=>{document.querySelector('#stage').classList.add('opening');setTimeout(()=>{document.querySelector('#stage').hidden=true;document.querySelector('#inside').hidden=false;document.querySelector('#back').focus();},reduced?0:1150);});document.querySelector('#back').addEventListener('click',()=>{document.querySelector('#inside').hidden=true;document.querySelector('#stage').hidden=false;document.querySelector('#stage').classList.remove('opening');document.querySelector('#enter').focus();});
